<p class="eyebrow">Reusable configuration</p><h1>Dynamic form builder</h1><section class="card"><h2>Create form</h2><form method="post" action="<?= e(route('admin.forms.save')) ?>" class="form-grid"><?= app('csrf')->input() ?><label>Name<input name="name" required></label><label>Internal key<input name="form_key" required></label><label>Purpose<select name="purpose"><option>DEPOSIT</option><option>WITHDRAWAL</option><option>KYC</option><option>GENERAL</option></select></label><button class="button">Create form</button></form></section><section class="card"><h2>Add field</h2><form method="post" action="<?= e(route('admin.forms.fields.add')) ?>" class="form-grid"><?= app('csrf')->input() ?><label>Form<select name="form_id"><?php foreach($forms as $form): ?><option value="<?= e($form['id']) ?>"><?= e($form['purpose'].' · '.$form['name']) ?></option><?php endforeach; ?></select></label><label>Label<input name="label" required></label><label>Field key<input name="field_key" required></label><label>Type<select name="field_type"><?php foreach(['TEXT','NUMBER','EMAIL','PHONE','TEXTAREA','SELECT','MULTI_SELECT','RADIO','CHECKBOX','DATE','FILE','COPYABLE_VALUE','INSTRUCTION'] as $type): ?><option><?= e($type) ?></option><?php endforeach; ?></select></label><label>Help text<input name="help_text"></label><label>Order<input name="sort_order" value="0"></label><label><input type="checkbox" name="required" value="1"> Required</label><button class="button">Add field</button></form></section><div class="table-wrap"><table><thead><tr><th>Purpose</th><th>Name</th><th>Key</th><th>Active</th></tr></thead><tbody><?php foreach($forms as $form): ?><tr><td><?= e($form['purpose']) ?></td><td><?= e($form['name']) ?></td><td><?= e($form['form_key']) ?></td><td><?= $form['active']?'Yes':'No' ?></td></tr><?php endforeach; ?></tbody></table></div>
